-- Organise the reviewed glossary into syllabus topics and a separate command-word section.
ALTER TABLE public.definitions ADD COLUMN IF NOT EXISTS category TEXT NOT NULL DEFAULT 'Other economic concepts';
WITH mapping(term, definition_text, category) AS (VALUES
  ('Scarcity', 'the fundamental economic problem that resources are finite/limited while human wants are unlimited.', 'Basic economic ideas and resource allocation'),
  ('Wants', 'desires for goods and services that give satisfaction; they are unlimited.', 'Basic economic ideas and resource allocation'),
  ('Resources (factors of production)', 'the inputs used to produce goods and services: land, labour, capital and enterprise.', 'Basic economic ideas and resource allocation'),
  ('Choice', 'the act of selecting between alternative uses of scarce resources, made necessary by scarcity.', 'Basic economic ideas and resource allocation'),
  ('Opportunity cost', 'the value of the next best alternative forgone when a choice is made.', 'Basic economic ideas and resource allocation'),
  ('Resource allocation', 'the process of deciding how scarce resources are distributed among competing uses.', 'Basic economic ideas and resource allocation'),
  ('What to produce', 'the decision about which goods and services, and in what quantities, should be produced.', 'Basic economic ideas and resource allocation'),
  ('How to produce', 'the decision about which methods/combinations of factors of production to use.', 'Basic economic ideas and resource allocation'),
  ('For whom to produce', 'the decision about how output is distributed among members of society.', 'Basic economic ideas and resource allocation'),
  ('Economics', 'the social science that studies how scarce resources are allocated to satisfy unlimited wants.', 'Basic economic ideas and resource allocation'),
  ('Social science', 'a discipline that studies human behaviour and society using scientific methods, but where controlled experiments are rarely possible.', 'Basic economic ideas and resource allocation'),
  ('Positive statement', 'a statement of fact that can be tested/verified against evidence (what is).', 'Basic economic ideas and resource allocation'),
  ('Normative statement', 'a statement involving a value judgement that cannot be scientifically proven (what ought to be).', 'Basic economic ideas and resource allocation'),
  ('Ceteris paribus', 'a Latin term meaning "other things being equal/held constant," used to isolate the effect of one variable.', 'Basic economic ideas and resource allocation'),
  ('Short run', 'the time period in which at least one factor of production is fixed.', 'Basic economic ideas and resource allocation'),
  ('Long run', 'the time period in which all factors of production are variable.', 'Basic economic ideas and resource allocation'),
  ('Very long run', 'the time period in which technology, population and institutions can change.', 'Basic economic ideas and resource allocation'),
  ('Land', 'all natural resources used in production (e.g. raw materials, minerals, agricultural land); its reward is rent.', 'Basic economic ideas and resource allocation'),
  ('Labour', 'the physical and mental human effort used in production; its reward is wages.', 'Basic economic ideas and resource allocation'),
  ('Capital', 'man-made resources used to produce other goods and services (machinery, buildings, infrastructure); its reward is interest.', 'Basic economic ideas and resource allocation'),
  ('Enterprise (entrepreneurship)', 'the factor that organises the other factors of production and bears risk; its reward is profit.', 'Basic economic ideas and resource allocation'),
  ('Human capital', 'the skills, knowledge, training and experience embodied in workers that raise their productivity.', 'Basic economic ideas and resource allocation'),
  ('Physical capital', 'man-made, tangible assets used in production, such as machinery and buildings.', 'Basic economic ideas and resource allocation'),
  ('Division of labour', 'breaking a production process into separate tasks performed by different workers.', 'Basic economic ideas and resource allocation'),
  ('Specialisation', 'concentrating on producing a narrow range of goods/services or tasks in which one has a comparative advantage.', 'Basic economic ideas and resource allocation'),
  ('Entrepreneur', 'an individual who takes on the risk of organising factors of production to produce goods/services in search of profit.', 'Basic economic ideas and resource allocation'),
  ('Market economy', 'an economic system in which resource allocation decisions are made through the price mechanism, with minimal government intervention.', 'Basic economic ideas and resource allocation'),
  ('Planned (command) economy', 'an economic system in which the government/state makes all resource allocation decisions.', 'Basic economic ideas and resource allocation'),
  ('Mixed economy', 'an economic system combining elements of market and planned economies, with both private markets and government intervention.', 'Basic economic ideas and resource allocation'),
  ('Production possibility curve (PPC)', 'a diagram showing the maximum combinations of two goods/services an economy can produce with given resources and technology, assuming full and efficient use of resources.', 'Basic economic ideas and resource allocation'),
  ('Constant opportunity cost', 'where the PPC is a straight line, meaning the same amount of one good must always be given up to produce an extra unit of another.', 'Basic economic ideas and resource allocation'),
  ('Increasing opportunity cost', 'where the PPC is concave (bowed outward from the origin), meaning progressively more of one good must be given up to produce additional units of another.', 'Basic economic ideas and resource allocation'),
  ('Outward shift of the PPC', 'represents economic growth, caused by an increase in resources or improved technology.', 'Basic economic ideas and resource allocation'),
  ('Inward shift of the PPC', 'represents a fall in productive potential, e.g. due to loss of resources or a disaster.', 'Basic economic ideas and resource allocation'),
  ('Point inside the PPC', 'represents unemployment or underutilisation of resources (productive inefficiency).', 'Basic economic ideas and resource allocation'),
  ('Point on the PPC', 'represents full and efficient use of resources.', 'Basic economic ideas and resource allocation'),
  ('Point outside the PPC', 'currently unattainable given existing resources and technology.', 'Basic economic ideas and resource allocation'),
  ('Free goods', 'goods that have no opportunity cost because they are not scarce (e.g. air).', 'Basic economic ideas and resource allocation'),
  ('Private (economic) goods', 'goods that are excludable and rivalrous, provided through the market; they have an opportunity cost.', 'Basic economic ideas and resource allocation'),
  ('Public goods', 'goods that are non-excludable and non-rivalrous, so the free market will fail to provide them (e.g. street lighting, national defence).', 'Basic economic ideas and resource allocation'),
  ('Non-excludability', 'it is impossible to prevent people who have not paid from consuming a good.', 'Basic economic ideas and resource allocation'),
  ('Non-rivalry', 'one person''s consumption does not reduce the amount available for others.', 'Basic economic ideas and resource allocation'),
  ('Free-rider problem', 'occurs when people benefit from a good without paying for it, discouraging private provision.', 'Basic economic ideas and resource allocation'),
  ('Merit goods', 'goods that are under-consumed relative to the socially optimal level because consumers underestimate their benefits (due to imperfect information), e.g. education, healthcare.', 'Basic economic ideas and resource allocation'),
  ('Demerit goods', 'goods that are over-consumed relative to the socially optimal level because consumers underestimate their costs/harms, e.g. tobacco, alcohol.', 'Basic economic ideas and resource allocation'),
  ('Demand', 'the quantity of a good/service that consumers are willing and able to buy at a given price over a given time period.', 'The price system and the microeconomy'),
  ('Effective demand', 'demand that is backed by the ability to pay (as opposed to mere desire).', 'The price system and the microeconomy'),
  ('Law of demand', 'as price rises, quantity demanded falls, ceteris paribus (inverse relationship).', 'The price system and the microeconomy'),
  ('Individual demand', 'the demand of a single consumer for a good.', 'The price system and the microeconomy'),
  ('Market demand', 'the sum of all individual demands for a good in a market.', 'The price system and the microeconomy'),
  ('Supply', 'the quantity of a good/service that producers are willing and able to sell at a given price over a given time period.', 'The price system and the microeconomy'),
  ('Law of supply', 'as price rises, quantity supplied rises, ceteris paribus (direct relationship).', 'The price system and the microeconomy'),
  ('Determinants of demand', 'factors other than price affecting demand: income, tastes/preferences, prices of substitutes/complements, population, advertising, expectations.', 'The price system and the microeconomy'),
  ('Determinants of supply', 'factors other than price affecting supply: costs of production, technology, number of producers, government taxes/subsidies, weather (for agriculture), expectations.', 'The price system and the microeconomy'),
  ('Shift in the demand curve', 'a movement of the whole curve caused by a change in a non-price determinant of demand.', 'The price system and the microeconomy'),
  ('Shift in the supply curve', 'a movement of the whole curve caused by a change in a non-price determinant of supply.', 'The price system and the microeconomy'),
  ('Movement along a curve (extension/contraction)', 'caused only by a change in the good''s own price.', 'The price system and the microeconomy'),
  ('Price elasticity of demand (PED)', 'the responsiveness of quantity demanded to a change in the price of the good itself. PED = %ΔQd / %ΔP.', 'The price system and the microeconomy'),
  ('Income elasticity of demand (YED)', 'the responsiveness of quantity demanded to a change in consumer income. YED = %ΔQd / %ΔY.', 'The price system and the microeconomy'),
  ('Cross elasticity of demand (XED)', 'the responsiveness of quantity demanded of one good to a change in the price of another good. XED = %ΔQd of A / %ΔP of B.', 'The price system and the microeconomy'),
  ('Perfectly elastic demand', 'PED = infinity; quantity demanded falls to zero for any price rise (horizontal curve).', 'The price system and the microeconomy'),
  ('Perfectly inelastic demand', 'PED = 0; quantity demanded does not change regardless of price (vertical curve).', 'The price system and the microeconomy'),
  ('Unitary elasticity', 'PED (or YED/XED) = 1 (ignoring sign); percentage change in quantity equals percentage change in the variable.', 'The price system and the microeconomy'),
  ('Elastic demand', 'PED > 1; quantity demanded changes proportionately more than price.', 'The price system and the microeconomy'),
  ('Inelastic demand', 'PED < 1; quantity demanded changes proportionately less than price.', 'The price system and the microeconomy'),
  ('Normal good', 'a good with positive YED; demand rises as income rises.', 'The price system and the microeconomy'),
  ('Inferior good', 'a good with negative YED; demand falls as income rises.', 'The price system and the microeconomy'),
  ('Luxury good', 'a normal good with YED > 1.', 'The price system and the microeconomy'),
  ('Necessity good', 'a normal good with YED between 0 and 1.', 'The price system and the microeconomy'),
  ('Substitute goods', 'goods with positive XED; a rise in the price of one increases demand for the other.', 'The price system and the microeconomy'),
  ('Complementary goods', 'goods with negative XED; a rise in the price of one decreases demand for the other.', 'The price system and the microeconomy'),
  ('Total expenditure/revenue', 'price multiplied by quantity; its response to a price change depends on PED.', 'The price system and the microeconomy'),
  ('Price elasticity of supply (PES)', 'the responsiveness of quantity supplied to a change in price. PES = %ΔQs / %ΔP.', 'The price system and the microeconomy'),
  ('Perfectly elastic supply', 'PES = infinity (horizontal supply curve).', 'The price system and the microeconomy'),
  ('Perfectly inelastic supply', 'PES = 0 (vertical supply curve).', 'The price system and the microeconomy'),
  ('Factors affecting PES', 'spare capacity, ease of factor substitution, time period, ability to store output, length of production period.', 'The price system and the microeconomy'),
  ('Market equilibrium', 'the price and quantity at which quantity demanded equals quantity supplied; no tendency for price to change.', 'The price system and the microeconomy'),
  ('Disequilibrium', 'a situation where quantity demanded and quantity supplied are not equal, causing excess demand or excess supply.', 'The price system and the microeconomy'),
  ('Excess demand (shortage)', 'occurs when price is below equilibrium; quantity demanded exceeds quantity supplied.', 'The price system and the microeconomy'),
  ('Excess supply (surplus)', 'occurs when price is above equilibrium; quantity supplied exceeds quantity demanded.', 'The price system and the microeconomy'),
  ('Joint demand (complements)', 'goods demanded together, so a change in demand for one affects demand for the other.', 'The price system and the microeconomy'),
  ('Alternative demand (substitutes)', 'goods that can be used in place of one another.', 'The price system and the microeconomy'),
  ('Derived demand', 'demand for a good/factor that arises from demand for another good (e.g. demand for labour derived from demand for the product it makes).', 'The price system and the microeconomy'),
  ('Joint supply', 'occurs when production of one good automatically results in production of another (e.g. beef and leather).', 'The price system and the microeconomy'),
  ('Rationing function of price', 'price allocates scarce goods to those willing and able to pay.', 'The price system and the microeconomy'),
  ('Signalling function of price', 'price changes convey information about relative scarcity/preferences to producers and consumers.', 'The price system and the microeconomy'),
  ('Incentive function of price', 'price changes provide incentives for producers/consumers to change behaviour.', 'The price system and the microeconomy'),
  ('Consumer surplus', 'the difference between what consumers are willing to pay for a good and what they actually pay; the area below the demand curve and above the price.', 'The price system and the microeconomy'),
  ('Producer surplus', 'the difference between what producers actually receive for a good and the minimum they would accept; the area above the supply curve and below the price.', 'The price system and the microeconomy'),
  ('Market failure', 'a situation in which the free market fails to allocate resources efficiently, leading to a net welfare loss.', 'Government microeconomic intervention'),
  ('Non-provision of public goods', 'the free market fails to provide public goods due to the free-rider problem.', 'Government microeconomic intervention'),
  ('Price control', 'government intervention to set prices above or below the market equilibrium.', 'Government microeconomic intervention'),
  ('Indirect tax', 'a tax on spending/expenditure, paid to the government by producers but often passed on to consumers (e.g. specific tax, ad valorem tax).', 'Government microeconomic intervention'),
  ('Specific tax', 'a fixed amount of tax per unit of a good.', 'Government microeconomic intervention'),
  ('Incidence of tax', 'the distribution of the tax burden between consumers and producers, depending on relative PED and PES.', 'Government microeconomic intervention'),
  ('Subsidy', 'a payment by the government to producers to lower production costs and encourage output/consumption.', 'Government microeconomic intervention'),
  ('Direct provision', 'the government itself produces and supplies goods/services (e.g. public healthcare).', 'Government microeconomic intervention'),
  ('Maximum price (price ceiling)', 'a legally imposed price set below equilibrium to make a good more affordable; can cause excess demand/shortages.', 'Government microeconomic intervention'),
  ('Minimum price (price floor)', 'a legally imposed price set above equilibrium to protect producers/workers; can cause excess supply/surplus.', 'Government microeconomic intervention'),
  ('Buffer stock scheme', 'a scheme where the government buys surplus output when price is low (stores it) and sells stock when price is high, to stabilise prices.', 'Government microeconomic intervention'),
  ('Provision of information', 'government action to correct imperfect information in markets (e.g. health warnings, labelling).', 'Government microeconomic intervention'),
  ('Income', 'a flow of earnings (wages, rent, interest, profit) received over a period of time.', 'Government microeconomic intervention'),
  ('Wealth', 'a stock of assets owned at a point in time (e.g. property, savings, shares).', 'Government microeconomic intervention'),
  ('Gini coefficient', 'a measure of income/wealth inequality ranging from 0 (perfect equality) to 1 (perfect inequality), derived from the Lorenz curve.', 'Government microeconomic intervention'),
  ('Minimum wage', 'a legally imposed wage floor set above the equilibrium wage to raise low incomes.', 'Government microeconomic intervention'),
  ('Transfer payments', 'payments made by the government to individuals for which no good/service is exchanged (e.g. benefits, pensions).', 'Government microeconomic intervention'),
  ('Progressive tax', 'a tax where the average rate of tax rises as income rises.', 'Government microeconomic intervention'),
  ('Inheritance tax', 'a tax on wealth transferred upon death.', 'Government microeconomic intervention'),
  ('Capital tax', 'a tax on wealth or capital gains.', 'Government microeconomic intervention'),
  ('National income', 'the total value of output, income or expenditure of an economy over a period, typically a year.', 'The macroeconomy: measures and performance'),
  ('Gross Domestic Product (GDP)', 'the total value of goods and services produced within a country''s borders in a given period.', 'The macroeconomy: measures and performance'),
  ('Gross National Income (GNI)', 'GDP plus net income earned by residents from overseas investments (minus income paid to foreign residents).', 'The macroeconomy: measures and performance'),
  ('Net National Income (NNI)', 'GNI minus depreciation (capital consumption).', 'The macroeconomy: measures and performance'),
  ('Market prices', 'values that include indirect taxes and exclude subsidies.', 'The macroeconomy: measures and performance'),
  ('Basic prices', 'values that exclude indirect taxes and include subsidies (reflecting what producers actually receive).', 'The macroeconomy: measures and performance'),
  ('Gross values', 'values that do not account for depreciation of capital.', 'The macroeconomy: measures and performance'),
  ('Net values', 'values that subtract depreciation of capital from gross values.', 'The macroeconomy: measures and performance'),
  ('Depreciation (capital consumption)', 'the fall in value of capital assets due to wear and tear/obsolescence.', 'The macroeconomy: measures and performance'),
  ('Circular flow of income', 'a model showing the flow of income and expenditure between households, firms, government and the international economy.', 'The macroeconomy: measures and performance'),
  ('Closed economy', 'an economy with no interaction (trade) with the rest of the world.', 'The macroeconomy: measures and performance'),
  ('Open economy', 'an economy that trades with other countries.', 'The macroeconomy: measures and performance'),
  ('Injections', 'additions to the circular flow of income: investment (I), government spending (G), exports (X).', 'The macroeconomy: measures and performance'),
  ('Leakages/withdrawals', 'income removed from the circular flow: savings (S), taxation (T), imports (M).', 'The macroeconomy: measures and performance'),
  ('Equilibrium national income', 'the level of income where injections equal leakages (or planned aggregate demand equals planned output).', 'The macroeconomy: measures and performance'),
  ('Aggregate Demand (AD)', 'the total demand for goods and services in an economy at a given price level over a given time period.', 'The macroeconomy: measures and performance'),
  ('AD = C + I + G + (X − M)', 'consumption + investment + government spending + net exports.', 'The macroeconomy: measures and performance'),
  ('Consumption (C)', 'total spending by households on goods and services.', 'The macroeconomy: measures and performance'),
  ('Investment (I)', 'spending by firms on capital goods.', 'The macroeconomy: measures and performance'),
  ('Government spending (G)', 'spending by the public sector on goods and services.', 'The macroeconomy: measures and performance'),
  ('Net exports (X − M)', 'exports minus imports.', 'The macroeconomy: measures and performance'),
  ('Aggregate Supply (AS)', 'the total output of goods and services that firms in an economy are willing and able to produce at a given price level.', 'The macroeconomy: measures and performance'),
