  ('Private benefits', 'benefits received directly by individuals/firms involved in an economic activity.', 'Consumer choice, efficiency and market failure'),
  ('External costs', 'costs of an economic activity borne by third parties not directly involved.', 'Consumer choice, efficiency and market failure'),
