  ('Macroeconomic policy objectives (A Level)', 'price stability, balance of payments equilibrium, low unemployment, economic growth, development, sustainability and equitable redistribution of income/wealth.', 'A Level macroeconomics'),
  ('Internal value of money', 'the purchasing power of money within a domestic economy (inversely related to inflation).', 'A Level macroeconomics'),
  ('External value of money', 'the value of a currency in terms of other currencies (the exchange rate).', 'A Level macroeconomics'),
  ('Phillips curve', 'a model showing an inverse (trade-off) relationship between the rate of unemployment and the rate of inflation.', 'A Level macroeconomics'),
