  ('Financial account', 'the section of the balance of payments recording flows of investment (FDI, portfolio investment) into and out of a country.', 'A Level macroeconomics'),
  ('Capital account', 'the section of the balance of payments recording capital transfers and transactions in non-produced, non-financial assets.', 'A Level macroeconomics'),
  ('Nominal exchange rate', 'the exchange rate expressed in money terms, not adjusted for price level differences.', 'A Level macroeconomics'),
  ('Real exchange rate', 'the exchange rate adjusted for relative price levels/inflation between two countries.', 'International economics and development'),
  ('Trade-weighted exchange rate', 'an index measuring the value of a currency against a basket of other currencies, weighted by trade importance.', 'International economics and development'),
  ('Fixed exchange rate', 'an exchange rate set and maintained by the government/central bank at a particular level against another currency.', 'International economics and development'),
  ('Managed (dirty) float', 'an exchange rate largely determined by market forces but with occasional government/central bank intervention.', 'International economics and development'),
  ('Devaluation', 'a deliberate reduction in the value of a fixed exchange rate by the government.', 'International economics and development'),
  ('Revaluation', 'a deliberate increase in the value of a fixed exchange rate by the government.', 'International economics and development'),
