  ('Economic development', 'a broad measure of improvement in living standards, including economic growth, health, education and quality of life.', 'International economics and development'),
  ('Purchasing power parity (PPP)', 'an exchange rate adjustment that equalises the purchasing power of different currencies, enabling fairer international income comparisons.', 'International economics and development'),
  ('Human Development Index (HDI)', 'a composite index measuring development based on life expectancy, education and income (GNI per capita).', 'International economics and development'),
  ('Measure of Economic Welfare (MEW)', 'an indicator adjusting GDP for factors affecting welfare not captured by GDP, such as leisure and pollution.', 'International economics and development'),
  ('Multidimensional Poverty Index (MPI)', 'a composite index measuring poverty based on multiple deprivations (e.g. health, education, living standards), not just income.', 'International economics and development'),
  ('Kuznets curve', 'a hypothesis suggesting income inequality first increases and then decreases as an economy develops (an inverted-U relationship).', 'International economics and development'),
  ('Birth rate', 'the number of live births per 1,000 of the population per year.', 'International economics and development'),
  ('Death rate', 'the number of deaths per 1,000 of the population per year.', 'International economics and development'),
  ('Infant mortality rate', 'the number of deaths of infants under one year old per 1,000 live births.', 'International economics and development'),
  ('Net migration', 'the difference between the number of people entering and leaving a country.', 'International economics and development'),
  ('Optimum population', 'the population size that maximises output/income per head, given available resources and technology.', 'International economics and development'),
  ('Urbanisation', 'the increasing proportion of a country''s population living in urban (town/city) areas.', 'International economics and development'),
  ('Lorenz curve', 'a graph showing the cumulative distribution of income/wealth across a population, used to derive the Gini coefficient.', 'International economics and development'),
