  ('Analyse', 'examine in detail to show meaning, identify elements and the relationship between them.', 'Command words'),
  ('Assess', 'make an informed judgement.', 'Command words'),
  ('Calculate', 'work out from given facts, figures or information.', 'Command words'),
  ('Comment', 'give an informed opinion.', 'Command words'),
  ('Compare', 'identify/comment on similarities and/or differences.', 'Command words'),
  ('Consider', 'review and respond to given information.', 'Command words'),
  ('Define', 'give precise meaning.', 'Command words'),
  ('Demonstrate', 'show how or give an example.', 'Command words'),
  ('Describe', 'state the points of a topic / give characteristics and main features.', 'Command words'),
  ('Discuss', 'write about issue(s) or topic(s) in depth in a structured way.', 'Command words'),
  ('Evaluate', 'judge or calculate the quality, importance, amount or value of something.', 'Command words'),
  ('Explain', 'set out purposes or reasons / make relationships clear / say why and/or how, supported with relevant evidence.', 'Command words'),
  ('Give', 'produce an answer from a given source or recall/memory.', 'Command words'),
  ('Identify', 'name/select/recognise.', 'Command words'),
  ('Justify', 'support a case with evidence/argument.', 'Command words'),
  ('Outline', 'set out the main points.', 'Command words'),
  ('__sentinel__', '', 'Other economic concepts')
)
UPDATE public.definitions d
SET category = m.category
FROM mapping m
WHERE m.term <> '__sentinel__'
  AND lower(trim(d.term)) = lower(trim(m.term))
  AND trim(d.definition_text) = trim(m.definition_text);

